@module modalHost  src=modalHost.lua  loc=160  mode=chunk  self=modalHost
@deps ctx, chrome

# Invariants & contracts
  @invariant  one modalHost per coordinator; threaded into every page that opens modals  @ 3
  @invariant  state.kind picks the render; built-ins are 'prompt' and 'confirm'; pages register custom kinds at load time  @ 4

# Shapes
  @shape  state = { kind, title, callback?, onClose?, flags?, ... per-kind fields }  @ 5

# Imports
  @require ImGui = 'imgui'  @ 7
      @contract  render(state, close) draws inside an active BeginPopupModal; close(invoke, ...args) captures+clears state, closes popup, pcalls callback if invoke, then pcalls onClose unconditionally  @ 6

# Private state
  @state POPUP_ID = '###modalHost'  @ 12
  @state kinds = {}  @ 14
  @state state = nil  @ 15
  @state wasOpen = false  @ 16   -- snapshot at tick(); stays true across the closing frame
  @state modalHost = {}  @ 20

# Private functions
  @fn label()  @ 18

# Handlers registered
  @handler modalHost:confirm(s, close)  @ 110-117
  @handler modalHost:prompt(s, close)  @ 119-158

# Public API (modalHost:*)
  @api modalHost:registerKind(kind, render)  @ 22
  @api modalHost:open(s)  @ 24-27
  @api modalHost:openPrompt(args)  @ 29-40
  @api modalHost:openConfirm(args)  @ 42-49
  @api modalHost:isOpen()  @ 51
  @api modalHost:wasOpenAtFrameStart()  @ 52
  @api modalHost:tick()  @ 54
  @api modalHost:draw()  @ 56-106

# Uses (outbound edges)
  @use call    ImGui.BeginPopupModal  @ draw:78
  @use call    ImGui.CloseCurrentPopup  @ draw:87
  @use call    ImGui.EndPopup  @ draw:99
  @use call    ImGui.GetStyleVar  @ draw:72
  @use call    ImGui.GetWindowViewport  @ draw:63
  @use call    ImGui.InputText  @ modalHost:prompt:132,147
  @use call    ImGui.IsItemActive  @ modalHost:prompt:149
  @use call    ImGui.IsKeyPressed  @ modalHost:confirm:112,114 modalHost:prompt:136,137,139,152
  @use call    ImGui.IsPopupOpen  @ draw:60
  @use call    ImGui.IsWindowAppearing  @ modalHost:prompt:120
  @use call    ImGui.OpenPopup  @ open:26 draw:61
  @use call    ImGui.PopStyleColor  @ draw:104
  @use call    ImGui.PopStyleVar  @ draw:79,103
  @use call    ImGui.PushStyleColor  @ draw:68
  @use call    ImGui.PushStyleVar  @ draw:69,73
  @use call    ImGui.SetKeyboardFocusHere  @ modalHost:prompt:121
  @use call    ImGui.SetNextWindowPos  @ draw:64
  @use call    ImGui.SetNextWindowSize  @ draw:76
  @use call    ImGui.Text  @ modalHost:confirm:111 modalHost:prompt:122,135
  @use call    ImGui.Viewport_GetCenter  @ draw:63
  @use call    chrome.colour  @ draw:68
  @use call    chrome.popChromeWindow  @ draw:105
  @use call    chrome.pushChromeWindow  @ draw:66
  @use call    chrome.selectTo  @ modalHost:prompt:146
  @use require imgui  @ <load>:7

# Calls (intra-file)
  @call label  @ open:26 draw:60,61,78
  @call modalHost:open  @ openPrompt:30 openConfirm:43
  @call modalHost:registerKind  @ <load>:110,119

# Unresolved receivers
  @drop s.onChord  @ modalHost:prompt:126
  @drop s.resolve  @ modalHost:prompt:134

# REAPER API surface
  @reaper ShowConsoleMsg

# Fields (r read / w write incl. constructor keys)
  @field r Col_TitleBgActive  @ draw:68
  @field r Cond_Appearing  @ draw:64,76
  @field r InputTextFlags_EnterReturnsTrue  @ modalHost:prompt:148
  @field r Key_Enter  @ modalHost:confirm:112 modalHost:prompt:136
  @field r Key_Escape  @ modalHost:confirm:114 modalHost:prompt:139,152
  @field r Key_KeypadEnter  @ modalHost:prompt:137
  @field r Key_N  @ modalHost:confirm:114
  @field r Key_Y  @ modalHost:confirm:112
  @field r StyleVar_FramePadding  @ draw:72,73
  @field r StyleVar_WindowRounding  @ draw:69
  @field r WindowFlags_AlwaysAutoResize  @ draw:77
  @field r buf  @ openPrompt:37 modalHost:prompt:132,147
  @field w buf  @ openPrompt:37 modalHost:prompt:133,155
  @field r callback  @ openPrompt:34 openConfirm:47 draw:81
  @field w callback  @ openPrompt:34 openConfirm:47
  @field r chrome  @ 10
  @field r ctx  @ 9
  @field r flags  @ draw:77
  @field r kind  @ draw:96,98
  @field w kind  @ openPrompt:31 openConfirm:44
  @field r onChord  @ openPrompt:36 modalHost:prompt:125
  @field w onChord  @ openPrompt:36
  @field r onClose  @ draw:82
  @field r prompt  @ openPrompt:33 openConfirm:46 modalHost:confirm:111 modalHost:prompt:122
  @field w prompt  @ openPrompt:33 openConfirm:46
  @field r resolve  @ openPrompt:35 modalHost:prompt:129
  @field w resolve  @ openPrompt:35
  @field r selectTo  @ openPrompt:38 modalHost:prompt:146,149
  @field w selectTo  @ openPrompt:38 modalHost:prompt:149
  @field r size  @ draw:76,77
